  ". Employees cannot register a face ID or be asked to verify — their Profile page shows “Contact admin to use this feature”, and no punch requires a face match.": "। কর্মচারীরা Face ID নিবন্ধন করতে পারবেন না বা যাচাই করতে বলা হবে না — তাদের প্রোফাইল পেজে “এই সুবিধা ব্যবহার করতে অ্যাডমিনের সঙ্গে যোগাযোগ করুন” দেখানো হয়, এবং কোনো পাঞ্চে ফেস মিল প্রয়োজন হয় না।",
