  "A fallback punch must still be from inside the office geofence. It is flagged on the punch and recorded in the Audit Log.": "বিকল্প পাঞ্চও অবশ্যই অফিসের জিওফেন্সের ভেতর থেকে হতে হবে। পাঞ্চে এটি চিহ্নিত থাকে এবং অডিট লগে নথিভুক্ত হয়।",
