  "Face ID verification is": "Face ID যাচাই",
  "for every employee. Every web punch needs a live face match against an approved Face ID; until one exists, web clock-in/out is blocked unless you allow the fallback below.": "প্রতিটি কর্মচারীর জন্য। প্রতিটি ওয়েব পাঞ্চে অনুমোদিত Face ID-র সঙ্গে লাইভ ফেস মিল প্রয়োজন; তা না থাকলে নিচের বিকল্প অনুমতি না দিলে ওয়েব ক্লক-ইন/আউট বন্ধ থাকে।",
  "Forgive late arrival when full hours are completed": "পূর্ণ ঘণ্টা সম্পন্ন হলে দেরিতে আসা মার্জনা করুন",
  "Grace Period (min)": "গ্রেস সময় (মিনিট)",
  "Half-Day Limit (hours or fewer)": "অর্ধদিবসের সীমা (এত ঘণ্টা বা কম)",
  "How many days back an employee can request work from home. Not allowed (recommended): today or a later date only, because an approved request for a past day relabels that day after the fact and the home-location check cannot be met.": "কর্মচারী কত দিন আগের জন্য বাড়ি থেকে কাজের অনুরোধ করতে পারেন। অনুমতি নেই (প্রস্তাবিত): শুধু আজ বা পরের তারিখ, কারণ অতীতের দিনের অনুমোদিত অনুরোধ পরে সেই দিনের অবস্থা বদলে দেয় এবং বাড়ির অবস্থান যাচাই পূরণ করা যায় না।",
