  "Not allowed (today or later)": "অনুমতি নেই (আজ বা পরে)",
  "Notify": "জানান",
  "Notify HR and the manager when an employee is absent for N+ consecutive working days without approved leave.": "কোনো কর্মচারী অনুমোদিত ছুটি ছাড়া টানা N+ কর্মদিবস অনুপস্থিত থাকলে এইচআর ও ম্যানেজারকে জানান।",
  "off": "বন্ধ",
  "Off (recommended): a finished day of the half-day limit or fewer is a Half Day; a day above it but short of the full-day minimum stays Present and is shown as “hours not completed” with the minutes short. On: every day below the full-day minimum is a Half Day.": "বন্ধ (প্রস্তাবিত): অর্ধদিবসের সীমা বা তার কম ঘণ্টায় শেষ হওয়া দিন অর্ধদিবস; সীমার বেশি কিন্তু পূর্ণ দিনের ন্যূনতমের কম হলে উপস্থিত থাকে এবং কত মিনিট কম তা সহ “ঘণ্টা পূর্ণ হয়নি” দেখানো হয়। চালু: পূর্ণ দিনের ন্যূনতমের কম প্রতিটি দিন অর্ধদিবস।",
  "OT Multiplier — Holiday": "ওভারটাইম গুণক — ছুটির দিন",
  "OT Multiplier — Regular": "ওভারটাইম গুণক — সাধারণ",
  "OT Threshold": "ওভারটাইমের সীমা",
  "Overtime Rules": "ওভারটাইমের নিয়ম",
  "Punch Rules": "পাঞ্চের নিয়ম",
  "Resets each calendar month": "প্রতি ক্যালেন্ডার মাসে রিসেট হয়",
  "Save All": "সব সংরক্ষণ করুন",
  "Shift End": "শিফট শেষ",
  "Shift Start": "শিফট শুরু",
  "Someone who arrives after the grace period but works the full-day hours is marked Present and gets no late mark. The late arrival stays as a note.": "যিনি গ্রেস সময়ের পরে আসেন কিন্তু পূর্ণ দিনের ঘণ্টা কাজ করেন তিনি উপস্থিত গণ্য হন এবং দেরি চিহ্ন পান না। দেরিতে আসা একটি নোট হিসেবে থেকে যায়।",
  "Treat every day below the full day as a Half Day": "পূর্ণ দিনের কম প্রতিটি দিনকে অর্ধদিবস গণ্য করুন",
