  "Up to 2 days back": "২ দিন আগে পর্যন্ত",
  "Up to 3 days back": "৩ দিন আগে পর্যন্ত",
  "Up to 7 days back": "৭ দিন আগে পর্যন্ত",
  "Who registers a Face ID": "কে Face ID নিবন্ধন করবেন",
  "Work-from-home requests may start in the past": "বাড়ি থেকে কাজের অনুরোধ অতীত থেকে শুরু হতে পারবে",
  "Worked hours after the break is deducted. Shift length minus the break makes overtime start exactly at shift end.": "বিরতি বাদ দেওয়ার পর কাজের ঘণ্টা। শিফটের দৈর্ঘ্য থেকে বিরতি বাদ দিলে ওভারটাইম ঠিক শিফট শেষে শুরু হয়।",
