  "Which weekly off pattern each employee follows. A new pattern applies from its effective date forward.": "প্রতিটি কর্মচারী কোন সাপ্তাহিক ছুটির প্যাটার্ন অনুসরণ করেন। নতুন প্যাটার্ন তার কার্যকর তারিখ থেকে সামনের দিকে প্রযোজ্য।",
  "\"{name}\" will be deactivated. Employees currently assigned this pattern keep it until reassigned — history is preserved.": "\"{name}\" নিষ্ক্রিয় করা হবে। বর্তমানে যে কর্মচারীদের এই প্যাটার্ন নির্ধারিত আছে, নতুন করে নির্ধারণ না করা পর্যন্ত তাঁদের কাছে এটি থাকবে — ইতিহাস সংরক্ষিত থাকে।",
