  "Not required of a private employer. Collect only where a government, PSU or aided establishment must report it, or a state incentive scheme requires it. Self-declared, and hidden from reporting managers.": "বেসরকারি নিয়োগকর্তার জন্য আবশ্যক নয়। শুধু সেখানেই সংগ্রহ করুন যেখানে সরকারি, PSU বা সাহায্যপ্রাপ্ত প্রতিষ্ঠানকে তা জানাতে হয়, বা রাজ্যের কোনো প্রণোদনা প্রকল্পে তা প্রয়োজন। স্ব-ঘোষিত, এবং রিপোর্টিং ম্যানেজারদের কাছে লুকানো থাকে।",
  "Nothing outstanding": "কিছু বাকি নেই",
  "Only required if a nominee above is under 18.": "উপরের কোনো মনোনীত ব্যক্তির বয়স ১৮-র কম হলেই কেবল আবশ্যক।",
  "OPTIONAL, not yet stored post-hire": "ঐচ্ছিক, নিয়োগের পরে এখনও সংরক্ষিত হয় না",
