  "Required for EPF Form 2. Nominees are picked from the family list, so a name is only typed once. Each scheme should total 100%.": "EPF ফর্ম 2-এর জন্য আবশ্যক। মনোনীত ব্যক্তিদের পরিবারের তালিকা থেকে বাছা হয়, তাই নাম একবারই লিখতে হয়। প্রতিটি প্রকল্পের মোট ১০০% হওয়া উচিত।",
