  "This account has no employee record on file (no employee number assigned), so employment, pay, statutory, and history details below are unavailable. This is expected for an admin/system login that was never onboarded as an employee — sign in as an onboarded employee to see a full record.": "এই অ্যাকাউন্টের কোনো কর্মচারী রেকর্ড নথিভুক্ত নেই (কোনো কর্মচারী নম্বর নির্ধারিত হয়নি), তাই নিচের কর্মসংস্থান, বেতন, বিধিবদ্ধ ও ইতিহাসের তথ্য উপলব্ধ নয়। যে অ্যাডমিন/সিস্টেম লগইন কখনও কর্মচারী হিসেবে অনবোর্ড হয়নি, তার ক্ষেত্রে এটাই প্রত্যাশিত — পূর্ণ রেকর্ড দেখতে অনবোর্ড হওয়া কোনো কর্মচারী হিসেবে সাইন ইন করুন।",
  "This employee submitted a bank detail change awaiting your review — their previous details remain active for payroll until you decide.": "এই কর্মচারী ব্যাংকের তথ্য পরিবর্তনের একটি অনুরোধ জমা দিয়েছেন যা আপনার পর্যালোচনার অপেক্ষায় — আপনি সিদ্ধান্ত না নেওয়া পর্যন্ত বেতনের জন্য তাঁর আগের তথ্যই সক্রিয় থাকবে।",
