  "Start a Hire action. HR completes the hiring form here, so this employee will go directly to their dashboard after their first password change rather than receiving the self-service onboarding wizard.": "একটি নিয়োগের পদক্ষেপ শুরু করুন। এইচআর এখানে নিয়োগ ফর্মটি পূরণ করে, তাই এই কর্মচারী স্ব-সেবা অনবোর্ডিং উইজার্ড না পেয়ে প্রথম পাসওয়ার্ড বদলানোর পর সরাসরি তাঁর ড্যাশবোর্ডে যাবেন।",
