  "Applied immediately — no pending-approval queue exists for this action yet.": "সঙ্গে সঙ্গে প্রয়োগ হয় — এই পদক্ষেপের জন্য এখনও কোনো অনুমোদনের অপেক্ষমাণ তালিকা নেই।",
