  "Current record will be delimited to {end}; the new record runs {start} → 31/12/9999.": "বর্তমান রেকর্ড {end} পর্যন্ত সীমাবদ্ধ করা হবে; নতুন রেকর্ড চলবে {start} → 31/12/9999।",
  "Failed to apply this action. Please try again.": "এই পদক্ষেপ প্রয়োগ করা যায়নি। অনুগ্রহ করে আবার চেষ্টা করুন।",
