  "Registering a face ID needs camera access. Allow it for this site in your browser's settings, then try again.": "Face ID নিবন্ধনের জন্য ক্যামেরা ব্যবহারের অনুমতি লাগে। আপনার ব্রাউজারের সেটিংসে এই সাইটের জন্য অনুমতি দিন, তারপর আবার চেষ্টা করুন।",
  "Registering face ID…": "Face ID নিবন্ধন হচ্ছে…",
  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure they're well-lit and centered, then try again.": "নিবন্ধনের জন্য স্বাভাবিক চোখের পলক ও সামান্য মাথা ঘোরানো দুটোই লাগে, কিন্তু সময়মতো দুটো দেখা যায়নি। নিশ্চিত করুন যে আলো যথেষ্ট ও মুখ মাঝখানে আছে, তারপর আবার চেষ্টা করুন।",
