  "The new hire registers their Face ID from their Profile page, and HR approves it on": "নতুন নিয়োগপ্রাপ্ত কর্মী তাঁর প্রোফাইল পেজ থেকে Face ID নিবন্ধন করেন এবং এইচআর তা অনুমোদন করে",
