  "The record is created in Onboarding status. Optional details (father/mother's name, non-required documents) can still be finished afterward.": "রেকর্ডটি অনবোর্ডিং অবস্থায় তৈরি হয়। ঐচ্ছিক তথ্য (বাবা/মায়ের নাম, অনাবশ্যক নথি) পরেও সম্পূর্ণ করা যায়।",
