  "Positions with nobody reporting to them and no one they report to. Set 'Reports to' on a position to place it in the chain.": "যে পজিশনে কেউ রিপোর্ট করে না এবং যে কারও কাছে রিপোর্ট করে না। শৃঙ্খলে বসাতে পজিশনে \"রিপোর্ট করেন\" নির্ধারণ করুন।",
