  ". Access belongs to that seat—not the reporting chain; employees sharing a seat share its permissions. Use separate positions when employees need different access.": "। অ্যাক্সেস সেই পদের — রিপোর্টিং শৃঙ্খলের নয়; একই পদে থাকা কর্মচারীরা এর অনুমতিগুলো ভাগ করে নেন। কর্মচারীদের ভিন্ন অ্যাক্সেস দরকার হলে আলাদা পজিশন ব্যবহার করুন।",
