  "Team manager": "টিম ম্যানেজার",
  "These permissions belong to this position. The current holder receives them; a future holder receives the same access. Permissions do not automatically pass between a manager and their reports. Give each position its own access below.": "এই অনুমতিগুলো এই পজিশনের। বর্তমান দায়িত্বপ্রাপ্ত ব্যক্তি এগুলো পান; ভবিষ্যতের দায়িত্বপ্রাপ্ত ব্যক্তিও একই অ্যাক্সেস পাবেন। অনুমতি স্বয়ংক্রিয়ভাবে ম্যানেজার ও তাঁর অধীনস্থদের মধ্যে যায় না। নিচে প্রতিটি পজিশনকে তার নিজস্ব অ্যাক্সেস দিন।",
  "Turning on Team manager also checked the usual manager permissions below (View employees, Approve leave, View attendance) so this position isn't left with 0 permissions. Uncheck any you don't want before saving.": "টিম ম্যানেজার চালু করায় নিচের সাধারণ ম্যানেজার অনুমতিগুলোও (কর্মচারী দেখুন, ছুটি অনুমোদন করুন, উপস্থিতি দেখুন) টিক করা হয়েছে, যাতে এই পজিশনে ০টি অনুমতি না থাকে। সংরক্ষণের আগে যেগুলো চান না সেগুলোর টিক তুলে দিন।",
