  "Salary transfer locked for {count} employee(s). Download the NEFT CSV and submit it to your bank before marking payroll paid.": "{count} জন কর্মচারীর বেতন স্থানান্তর লক করা হয়েছে। বেতন পরিশোধিত চিহ্নিত করার আগে NEFT CSV ডাউনলোড করে আপনার ব্যাংকে জমা দিন।",
  "Salary transfer readiness is unavailable.": "বেতন স্থানান্তরের প্রস্তুতির তথ্য উপলব্ধ নয়।",
  "This locks the current bank details and net pay for all {count} employee(s) into a transfer batch. Download the NEFT CSV after confirmation and submit it through your bank before marking payroll paid.": "এটি সব {count} জন কর্মচারীর বর্তমান ব্যাংকের তথ্য ও নিট বেতন একটি স্থানান্তর ব্যাচে লক করে। নিশ্চিত করার পর NEFT CSV ডাউনলোড করুন এবং বেতন পরিশোধিত চিহ্নিত করার আগে আপনার ব্যাংকের মাধ্যমে জমা দিন।",
  "This marks all {count} payslip (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "এটি সব {count}টি বেতন স্লিপ (মোট {amount}) পরিশোধিত হিসেবে চিহ্নিত করে এবং এই বেতন প্রক্রিয়া বন্ধ করে। এটি নিজে টাকা স্থানান্তর করে না — স্থানান্তর ইতিমধ্যে হয়ে গেছে তা নথিভুক্ত করে। এটি পূর্বাবস্থায় ফেরানো যাবে না।",
  "This marks all {count} payslips (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "এটি সব {count}টি বেতন স্লিপ (মোট {amount}) পরিশোধিত হিসেবে চিহ্নিত করে এবং এই বেতন প্রক্রিয়া বন্ধ করে। এটি নিজে টাকা স্থানান্তর করে না — স্থানান্তর ইতিমধ্যে হয়ে গেছে তা নথিভুক্ত করে। এটি পূর্বাবস্থায় ফেরানো যাবে না।",
