  "This recalculates salaries for all {count} employee in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "এটি এই পর্বের সব {count} জন কর্মচারীর বেতন শুরু থেকে আবার গণনা করে বর্তমান অঙ্কগুলো বদলে দেয় — এই বেতন স্লিপগুলোতে আগে করা যেকোনো ম্যানুয়াল বোনাস বা প্রতিপূরণ সমন্বয়সহ। এটি পূর্বাবস্থায় ফেরানো যাবে না।",
  "This recalculates salaries for all {count} employees in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "এটি এই পর্বের সব {count} জন কর্মচারীর বেতন শুরু থেকে আবার গণনা করে বর্তমান অঙ্কগুলো বদলে দেয় — এই বেতন স্লিপগুলোতে আগে করা যেকোনো ম্যানুয়াল বোনাস বা প্রতিপূরণ সমন্বয়সহ। এটি পূর্বাবস্থায় ফেরানো যাবে না।",
  "This will calculate salaries for all eligible employees using their CTC, salary structure, and statutory rules for each branch.": "এটি প্রতিটি শাখার জন্য CTC, বেতন কাঠামো ও বিধিবদ্ধ নিয়ম অনুযায়ী সব যোগ্য কর্মচারীর বেতন গণনা করবে।",
