  "Other Adjustment: {amount}": "অন্যান্য সমন্বয়: {amount}",
  "Pro-rata Salary": "আনুপাতিক বেতন",
  "Pro-rated salary, leave encashment, and notice-period shortfall are computed automatically (CTC ÷ 30, Earned Leave balance) — a starting estimate to review, not a final figure. Gratuity, bonus, reimbursements, advances, and TDS are always entered by hand.": "আনুপাতিক বেতন, ছুটি নগদায়ন ও নোটিশ সময়ের ঘাটতি স্বয়ংক্রিয়ভাবে গণনা হয় (CTC ÷ 30, অর্জিত ছুটির ব্যালেন্স) — এটি পর্যালোচনার জন্য প্রাথমিক অনুমান, চূড়ান্ত অঙ্ক নয়। গ্র্যাচুইটি, বোনাস, প্রতিপূরণ, অগ্রিম ও TDS সবসময় নিজে লিখতে হয়।",
  "Settlement finalized.": "নিষ্পত্তি চূড়ান্ত হয়েছে।",
  "Settlement updated.": "নিষ্পত্তি হালনাগাদ হয়েছে।",
  "This is a recovery — the employee owes the company (net payable may be negative)": "এটি একটি আদায় — কর্মচারী কোম্পানির কাছে ঋণী (প্রদেয় নিট ঋণাত্মক হতে পারে)",
  "This locks the full & final settlement at a net payable of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "এটি পূর্ণ ও চূড়ান্ত নিষ্পত্তিকে {amount} প্রদেয় নিট অঙ্কে লক করে। চূড়ান্ত হওয়ার পর এই নিষ্পত্তির কোনো ঘর — গ্র্যাচুইটি, বোনাস, প্রতিপূরণ, অগ্রিম, TDS বা সমন্বয় — আর সম্পাদনা করা যাবে না। এটি পূর্বাবস্থায় ফেরানো যাবে না।",
  "This locks the full & final settlement at a net recoverable from the employee of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "এটি পূর্ণ ও চূড়ান্ত নিষ্পত্তিকে কর্মচারীর কাছ থেকে {amount} আদায়যোগ্য নিট অঙ্কে লক করে। চূড়ান্ত হওয়ার পর এই নিষ্পত্তির কোনো ঘর — গ্র্যাচুইটি, বোনাস, প্রতিপূরণ, অগ্রিম, TDS বা সমন্বয় — আর সম্পাদনা করা যাবে না। এটি পূর্বাবস্থায় ফেরানো যাবে না।",
