  "Statutory and business details. The form adapts to your entity type, so you only see what applies to you.": "বিধিবদ্ধ ও ব্যবসায়িক তথ্য। ফর্মটি আপনার প্রতিষ্ঠানের ধরন অনুযায়ী বদলায়, তাই শুধু প্রযোজ্য অংশই দেখতে পাবেন।",
