  "Add the people who depend on the employee or who may be nominated below. A person is added once and can be picked as a nominee.": "যাঁরা কর্মচারীর উপর নির্ভরশীল বা যাঁদের মনোনীত করা হতে পারে, তাঁদের নিচে যোগ করুন। একজন ব্যক্তি একবারই যোগ হন এবং মনোনীত ব্যক্তি হিসেবে বাছাই করা যায়।",
