  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, and it takes effect immediately.": "ওয়েব ক্লক-ইন/আউটের জন্য আপনার প্রতিষ্ঠানে নিবন্ধিত Face ID প্রয়োজন। এখানে একবার নিবন্ধন করুন — এটি সত্যিই আপনি কিনা নিশ্চিত করতে আমরা একটি দ্রুত লাইভনেস পরীক্ষা চালাই, এবং এটি সঙ্গে সঙ্গে কার্যকর হয়।",
