  "{count} employee has no joining date. They are left out of attendance and payroll until HR corrects it.": "{count} জন কর্মচারীর যোগদানের তারিখ নেই। এইচআর সংশোধন না করা পর্যন্ত তাঁকে উপস্থিতি ও বেতন প্রক্রিয়া থেকে বাদ রাখা হয়েছে।",
  "{count} employees have no joining date. They are left out of attendance and payroll until HR corrects it.": "{count} জন কর্মচারীর যোগদানের তারিখ নেই। এইচআর সংশোধন না করা পর্যন্ত তাঁদের উপস্থিতি ও বেতন প্রক্রিয়া থেকে বাদ রাখা হয়েছে।",
  "Show them": "তাঁদের দেখান",
  "View workspace": "ওয়ার্কস্পেস দেখুন",
