  "Make sure you place your face inside the frame": "আপনার মুখ ফ্রেমের ভেতরে রাখুন",
  "Slowly turn your head slightly to one side, then back": "ধীরে ধীরে মাথা সামান্য একপাশে ঘোরান, তারপর আবার সামনে আনুন",
  "Biometric data consent": "বায়োমেট্রিক তথ্যের সম্মতি",
  "I Agree & Continue": "আমি সম্মত, এগিয়ে যান",
  "I have read and agree to the above.": "আমি উপরের বিষয়গুলো পড়েছি এবং সম্মত।",
  "Face ID registration was rejected": "Face ID নিবন্ধন প্রত্যাখ্যান করা হয়েছে",
  "Face ID waiting for approval": "Face ID অনুমোদনের অপেক্ষায়",
  "Register your Face ID": "আপনার Face ID নিবন্ধন করুন",
  "Couldn't confirm you're live": "আপনি সরাসরি উপস্থিত কিনা নিশ্চিত করা যায়নি",
  "Face registration needs your camera. Allow camera access for this site in your browser's settings, then try again.": "মুখ নিবন্ধনের জন্য আপনার ক্যামেরা প্রয়োজন। আপনার ব্রাউজারের সেটিংসে এই সাইটের জন্য ক্যামেরার অ্যাক্সেস দিন, তারপর আবার চেষ্টা করুন।",
  "Register your face": "আপনার মুখ নিবন্ধন করুন",
  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure you're well-lit and centered, then try again.": "নিবন্ধনের জন্য স্বাভাবিক চোখ পিটপিট ও সামান্য মাথা ঘোরানো দুটোই প্রয়োজন, কিন্তু সময়মতো দুটো দেখা যায়নি। পর্যাপ্ত আলো আছে ও মুখ মাঝখানে আছে নিশ্চিত করে আবার চেষ্টা করুন।",
  "Registration submitted!": "নিবন্ধন জমা হয়েছে!",
  "Sending your registration for approval…": "অনুমোদনের জন্য আপনার নিবন্ধন পাঠানো হচ্ছে…",
  "Submitting": "জমা হচ্ছে",
  "Update your face ID": "আপনার Face ID আপডেট করুন",
  "We couldn't get a reliably clear capture — this becomes your permanent face ID reference, so it's worth getting right. Try better lighting and hold steady.": "নির্ভরযোগ্য স্পষ্ট ছবি পাওয়া যায়নি — এটি আপনার স্থায়ী Face ID রেফারেন্স হবে, তাই সঠিকভাবে নেওয়া জরুরি। ভালো আলোতে স্থির থেকে আবার চেষ্টা করুন।",
  "We'll ask for camera access, run a quick liveness check (a blink and a slight head turn) to confirm it's really you, then send your face ID for HR approval. No photo or video is ever sent — only a numeric face signature.": "আমরা ক্যামেরার অ্যাক্সেস চাইব, আপনিই যে আসল ব্যক্তি তা নিশ্চিত করতে একটি দ্রুত লাইভনেস যাচাই (একবার চোখ পিটপিট ও সামান্য মাথা ঘোরানো) করব, তারপর এইচআরের অনুমোদনের জন্য আপনার Face ID পাঠাব। কোনো ছবি বা ভিডিও পাঠানো হয় না — শুধু একটি সংখ্যাভিত্তিক মুখের স্বাক্ষর পাঠানো হয়।",
  "We'll ask for camera access, run a quick liveness check (a blink and a slight head turn) to confirm it's really you, then send your updated face ID for HR approval. No photo or video is ever sent — only a numeric face signature.": "আমরা ক্যামেরার অ্যাক্সেস চাইব, আপনিই যে আসল ব্যক্তি তা নিশ্চিত করতে একটি দ্রুত লাইভনেস যাচাই (একবার চোখ পিটপিট ও সামান্য মাথা ঘোরানো) করব, তারপর এইচআরের অনুমোদনের জন্য আপনার আপডেট করা Face ID পাঠাব। কোনো ছবি বা ভিডিও পাঠানো হয় না — শুধু একটি সংখ্যাভিত্তিক মুখের স্বাক্ষর পাঠানো হয়।",
  "Your face registration request has been sent to HR for approval. You'll be notified once it's reviewed.": "আপনার মুখ নিবন্ধনের অনুরোধ অনুমোদনের জন্য এইচআরের কাছে পাঠানো হয়েছে। পর্যালোচনা শেষ হলে আপনাকে জানানো হবে।",
  "Low light detected — your screen is now acting as a light. Raising your screen brightness helps.": "আলো কম — আপনার স্ক্রিন এখন আলো হিসেবে কাজ করছে। স্ক্রিনের উজ্জ্বলতা বাড়ালে সাহায্য হবে।",
  "Please allow camera access in the browser prompt to punch in or out.": "পাঞ্চ ইন বা আউট করতে ব্রাউজারের বার্তায় ক্যামেরার অ্যাক্সেস দিন।",
  "Preparing face verification": "মুখ যাচাইয়ের প্রস্তুতি চলছে",
  "Verify Your Identity": "আপনার পরিচয় যাচাই করুন",
  "We couldn't get a reliably clear capture to verify against your registered face. Try better lighting and hold steady.": "আপনার নিবন্ধিত মুখের সঙ্গে মেলানোর জন্য নির্ভরযোগ্য স্পষ্ট ছবি পাওয়া যায়নি। ভালো আলোতে স্থির থেকে আবার চেষ্টা করুন।",
  "We didn't detect a slight head turn in time. Make sure you're well-lit and centered, then try again.": "সময়মতো সামান্য মাথা ঘোরানো শনাক্ত হয়নি। পর্যাপ্ত আলো আছে ও মুখ মাঝখানে আছে নিশ্চিত করে আবার চেষ্টা করুন।",
  "Your account requires face verification to punch in or out. Allow camera access for this site in your browser's settings, then try again.": "পাঞ্চ ইন বা আউট করতে আপনার অ্যাকাউন্টে মুখ যাচাই প্রয়োজন। আপনার ব্রাউজারের সেটিংসে এই সাইটের জন্য ক্যামেরার অ্যাক্সেস দিন, তারপর আবার চেষ্টা করুন।",
